<script setup>
import { computed, onMounted, onBeforeUnmount, ref, watch } from 'vue'
import { RefreshCw, ArrowUpRight, ChevronLeft, ChevronRight, Wallet, ChartNoAxesCombined, ReceiptText, X } from 'lucide-vue-next'
import { api } from '../api'
import { beijingDay, financeReport, financeTime, eventAmountR, cents, money, financeEventPeriod } from '../ejh-finance'
import Pagination from './Pagination.vue'
import { ejhPageRefreshSeconds } from '../ejhRefresh'
const props=defineProps({defaultPageSize:{type:Number,default:10}})
const data=ref(null),history=ref({}),busy=ref(false),error=ref(''),updated=ref('')
const mode=ref('all'),date=ref(beijingDay()),kind=ref(''),query=ref(''),dayFilter=ref(''),page=ref(1),pageSize=ref(props.defaultPageSize || 10),detail=ref(null)
let disposed=false,timer
const refreshSeconds=computed(()=>ejhPageRefreshSeconds(data.value?.page_refresh_seconds))
const periodEditor=ref(false),historyMonth=ref(''),savingPeriod=ref(false)
function editPeriod(){historyMonth.value=data.value?.recharge_ledger?.history_month||beijingDay().slice(0,7);periodEditor.value=true}
async function savePeriod(){
 savingPeriod.value=true;error.value=''
 try{const ledger=await api('/api/ejh/recharge-period',{method:'PUT',body:{month:historyMonth.value}});data.value={...data.value,recharge_ledger:ledger};periodEditor.value=false;await load()}catch(e){error.value=e.message}finally{savingPeriod.value=false}
}
const labels={opening:'开卡费',reversal:'授权撤销费',recharge:'充值手续费',clearing:'清算成本',refund:'清算退款手续费',consumption:'消费收益'}
const report=computed(()=>financeReport(data.value||{},history.value,mode.value,date.value))
const summary=computed(()=>report.value.summary)
const overview=computed(()=>report.value.overview)
const trends=computed(()=>report.value.rows.filter(r=>r.day!=='未分期历史').slice(0,31).reverse())
const earnings=computed(()=>summary.value.earnings)
const trendMax=computed(()=>Object.fromEntries(['costR','profitR'].map(field=>[field,Math.max(1,...trends.value.map(r=>Math.abs(Number(r.earnings[field])||0)))])))
const filtered=computed(()=>report.value.events.filter(e=>(!kind.value||e.kind===kind.value)&&(!dayFilter.value||financeEventPeriod(e,mode.value)===dayFilter.value)&&[e.email,e.card,e.reference,e.note].join(' ').toLowerCase().includes(query.value.trim().toLowerCase())))
const visible=computed(()=>filtered.value.slice((page.value-1)*pageSize.value,page.value*pageSize.value))
const when=value=>{const n=typeof value==='number'?value:financeTime(value);return n===null?'未分期历史':new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(n)}
const numR=value=>value===null?'—':Number(value).toFixed(4)
const numMoney=value=>money(cents(value))??'待核实'
watch([mode,date],()=>{page.value=1;dayFilter.value='';detail.value=null})
watch([kind,query,dayFilter,pageSize],()=>page.value=1)
watch(()=>filtered.value.length,()=>{page.value=Math.min(page.value,Math.max(1,Math.ceil(filtered.value.length/pageSize.value)))})
async function load(){
 if(busy.value)return
 busy.value=true;error.value=''
 try{const [a,b]=await Promise.all([api('/api/ejh/dashboard'),api('/api/ejh/finance')]);if(!disposed){data.value=a;history.value=b;updated.value=a.server_time||new Date().toISOString()}}
 catch(e){if(!disposed)error.value=e.message}
 finally{if(!disposed){busy.value=false;clearTimeout(timer);timer=setTimeout(load,refreshSeconds.value*1000)}}
}
function shift(direction){
 const at=financeTime(date.value+'T12:00:00+08:00');if(at===null)return
 if(mode.value==='month'){const d=new Date(at+8*3600000);d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+direction);date.value=beijingDay(d.getTime()-8*3600000)}
 else date.value=beijingDay(at+direction*(mode.value==='week'?7:1)*86400000)
}
function showDay(day){dayFilter.value=day;document.querySelector('#ejh-finance-details')?.scrollIntoView({behavior:'smooth',block:'start'})}
onMounted(load)
onBeforeUnmount(()=>{disposed=true;clearInterval(timer)})
</script>
<template>
 <div class="finance-page">
  <header class="finance-heading"><div><span class="eyebrow">EJH · COST & PROFIT</span><h1>成本统计</h1><p>消费收益 − 全部成本 = 净利润 · 1 USD = 6.7 R</p></div><button class="btn ghost" :disabled="busy" @click="load"><RefreshCw :size="14" :class="{spin:busy}"/>{{busy?'更新中…':'刷新统计'}}</button></header>
  <form v-if="periodEditor" class="period-toolbar" @submit.prevent="savePeriod"><label>历史充值归属月份 <input v-model="historyMonth" type="month" required aria-label="历史充值归属月份"/></label><small>只调整历史充值手续费归属，不改变充值金额；具体日期未知时仅计入月报。</small><button class="btn primary" :disabled="savingPeriod">{{savingPeriod?'保存中…':'保存'}}</button><button type="button" class="btn ghost" :disabled="savingPeriod" @click="periodEditor=false">取消</button></form>
  <p v-if="report.monthlyUndated&&['day','week'].includes(mode)" class="finance-notice">有历史充值只确认了月份，尚未分摊到具体日期；该笔手续费已计入对应月报和全部统计。</p>
  <div class="period-toolbar"><div class="period-switch" role="group" aria-label="统计周期"><button v-for="[value,label] in [['day','每天'],['week','每周'],['month','每月'],['all','全部']]" :key="value" :aria-pressed="mode===value" :class="{active:mode===value}" @click="mode=value">{{label}}</button></div><div v-if="mode!=='all'" class="date-controls"><button class="icon-button" aria-label="上一期" @click="shift(-1)"><ChevronLeft :size="16"/></button><input v-model="date" type="date" aria-label="统计日期"/><button class="icon-button" aria-label="下一期" @click="shift(1)"><ChevronRight :size="16"/></button><button class="today" @click="date=beijingDay()">今天</button></div><button class="today" :disabled="!data||busy" @click="editPeriod">充值归属</button><span class="period-label">{{report.range.label}} · 北京时间</span></div>
  <div v-if="error" class="finance-error" role="alert">{{data?'刷新失败，保留上次数据：':''}}{{error}} <button @click="load">重试</button></div>
  <div v-if="!data" class="finance-loading" role="status">{{busy?'正在读取收益与成本记录…':'暂无可用数据'}}</div>
  <template v-else>
   <div v-if="history.recording?.error" class="finance-error" role="alert">历史记录保存失败：{{history.recording.error}}。现有统计保留，后台将重试。</div>
   <div class="finance-heroes">
    <section class="hero usage"><div class="hero-label"><ChartNoAxesCombined :size="17"/>本期消费收益</div><div class="hero-number">{{earnings.consumptionR??'—'}} <small>R</small></div><div class="hero-secondary">{{mode==='all'?'累计用户消费':'本期实际用户扣费'}}</div><p>扣除全部成本前的收益</p></section>
    <section class="hero cost"><div class="hero-label"><Wallet :size="17"/>本期总成本 <span v-if="earnings.costIncomplete">数据不完整</span><span v-else-if="earnings.estimated">估算</span></div><div class="hero-number">{{earnings.costR??'—'}} <small>R</small></div><div class="hero-secondary">{{earnings.costIncomplete?'已知 '+(earnings.knownCostUSD??'—')+' USD':(earnings.costUSD??'—')+' USD'}}</div><p>开卡费 + 充值手续费 + 撤销费 + 清算 + 退款费</p></section>
    <section class="hero profit" :class="{negative:earnings.profitR?.startsWith('-')}"><div class="hero-label"><ReceiptText :size="17"/>本期净利润 <span v-if="earnings.estimated">估算</span></div><div class="hero-number">{{earnings.profitR??'—'}} <small>R</small></div><div class="hero-secondary">消费收益 − 总成本</div><p>{{earnings.incomplete?'数据未完整，暂不计算净利润':'已扣除开卡、充值、撤销、清算及退款费用'}}</p></section>
   </div>
   <div class="finance-breakdown">
    <button :class="{selected:kind==='opening'}" @click="kind=kind==='opening'?'':'opening'"><span>开卡费 <ArrowUpRight :size="14"/></span><strong>{{earnings.openingR}} <em>R</em></strong><small>{{summary.usdt}} USDT · {{summary.opening}} 张 × 0.50（含已销卡）</small></button>
    <button :class="{selected:kind==='recharge'}" @click="kind=kind==='recharge'?'':'recharge'"><span>充值手续费 <ArrowUpRight :size="14"/></span><strong>{{earnings.rechargeR??'—'}} <em>R</em></strong><small>{{summary.rechargeUSD??'—'}} USD · 充值金额 × 1%</small></button>
    <button :class="{selected:kind==='reversal'}" @click="kind=kind==='reversal'?'':'reversal'"><span>授权撤销费 <ArrowUpRight :size="14"/></span><strong>{{earnings.reversalR??'—'}} <em>R</em></strong><small>{{summary.reversalUSD}} USD · 按 {{data.reversal_fee_percent??6}}% 估算</small><small>{{summary.original.map(r=>r.amount+' '+r.currency).join(' / ')||'暂无已知撤销费用'}}</small></button>
    <button :class="{selected:kind==='clearing'}" @click="kind=kind==='clearing'?'':'clearing'"><span>清算成本 <ArrowUpRight :size="14"/></span><strong>{{earnings.clearingR??'—'}} <em>R</em></strong><small>{{summary.clearingUSD??'—'}} USD · 已入账清算</small></button>
    <button :class="{selected:kind==='refund'}" @click="kind=kind==='refund'?'':'refund'"><span>清算退款手续费 <ArrowUpRight :size="14"/></span><strong>{{earnings.refundR??'—'}} <em>R</em></strong><small>{{summary.refundUSD??'—'}} USD · 按核对登记</small></button>
   </div>
   <div v-if="report.baseline||report.undated||summary.missing||overview.consumption.missing||earnings.costIncomplete||report.dailyPending||report.periodIncomplete" class="finance-notice"><span v-if="report.periodIncomplete">分期收支尚未核对完整，暂不计算分期净利润。 </span><span v-if="report.dailyPending">{{report.dailyPending}} 个账号等待按实际日期核对<span v-if="report.dailyErrors">（{{report.dailyErrors}} 个查询异常，保留原数据）</span>。 </span><span v-if="report.baseline">历史累计 {{numR(report.baseline)}} R 未分期，计入“全部”。 </span><span v-if="report.undated">{{report.undated}} 笔历史费用无日期，仅计入“全部”。 </span><span v-if="summary.missing||earnings.costIncomplete">部分数据待核实，当前合计不完整。 </span><span v-if="overview.consumption.missing">{{overview.consumption.missing}} 个账号消费尚未查询。 </span></div>
   <div class="finance-charts"><section v-for="[field,title] in [['costR','成本趋势'],['profitR','净利润趋势']]" :key="field" class="finance-panel"><div class="panel-heading"><h2>{{title}}</h2><small>{{mode==='all'?'最近 31 个有记录的月份':'按日'}} · R</small></div><div v-if="trends.length" class="trend-bars" :aria-label="title"><button v-for="row in trends" :key="row.day" class="trend-column" :title="row.day+'：'+(row.earnings[field]??'待核实')+' R'" @click="showDay(row.day)"><span class="bar-track"><i v-if="row.earnings[field]!==null" :style="{height:Math.max(2,Math.abs(Number(row.earnings[field])||0)/trendMax[field]*100)+'%'}" :class="{usage:field==='profitR',negative:Number(row.earnings[field])<0}"></i></span><small>{{row.day.slice(mode==='all'?2:5)}}</small><strong>{{row.earnings[field]===null?'—':Number(row.earnings[field]).toFixed(2)}}</strong></button></div><div v-else class="chart-empty">本期暂无分期记录</div></section></div>
   <section class="finance-panel"><div class="panel-heading"><h2>{{mode==='all'?'按月汇总':'每日明细'}}</h2><small>按已记录数据统计 · 点击日期查看明细</small></div><div class="finance-table"><table><thead><tr><th>日期</th><th>消费收益 R</th><th>开卡费 R</th><th>充值手续费 R</th><th>授权撤销费 R</th><th>清算成本 R</th><th>退款手续费 R</th><th>总成本 R</th><th>净利润 R</th></tr></thead><tbody><tr v-for="row in report.rows" :key="row.day"><td><button class="text-link" @click="showDay(row.day)">{{row.day}}</button><small v-if="row.missing" class="table-warning">部分待核实</small></td><td>{{row.earnings.consumptionR??'—'}}</td><td>{{row.earnings.openingR??'—'}}</td><td>{{row.earnings.rechargeR??'—'}}</td><td>{{row.earnings.reversalR??'—'}}</td><td>{{row.earnings.clearingR??'—'}}</td><td>{{row.earnings.refundR??'—'}}</td><td>{{row.earnings.costR??'—'}}</td><td class="profit-value" :class="{negative:row.earnings.profitR?.startsWith('-')}">{{row.earnings.profitR??'—'}}</td></tr><tr v-if="!report.rows.length"><td colspan="9" class="empty">本期暂无记录</td></tr></tbody></table></div></section>
   <section id="ejh-finance-details" class="finance-panel"><div class="panel-heading"><h2>收益与成本明细 <small>{{filtered.length}} 条</small></h2><button v-if="dayFilter" class="text-link" @click="dayFilter=''">{{dayFilter}} ×</button></div><div class="detail-filters"><select v-model="kind" aria-label="明细类型"><option value="">全部类型</option><option v-for="(label,key) in labels" :key="key" :value="key">{{label}}</option></select><input v-model="query" type="search" aria-label="搜索账号、卡片或流水" placeholder="搜索账号、卡片或流水"/></div><div class="finance-table"><table><thead><tr><th>时间</th><th>类型</th><th>卡片 / 账号</th><th>金额 R</th><th>原币 / USD</th><th></th></tr></thead><tbody><tr v-for="entry in visible" :key="entry.id"><td>{{entry.day||(entry.month?(entry.month+'（日期未记录）'):when(entry.at))}}</td><td><span class="entry-kind" :class="entry.kind">{{labels[entry.kind]}}</span></td><td>{{entry.email||entry.card||'—'}}</td><td><strong>{{eventAmountR(entry)??'待核实'}}</strong></td><td>{{entry.amount===null?'待核实':entry.kind==='consumption'?numR(entry.amount):numMoney(entry.amount)}} {{entry.currency}}<small v-if="['reversal','clearing'].includes(entry.kind)&&entry.currency!=='USD'">{{numMoney(entry.usd)}} USD</small></td><td><button class="text-link" @click="detail=entry">详情</button></td></tr><tr v-if="!visible.length"><td colspan="6" class="empty">没有匹配的记录</td></tr></tbody></table></div><Pagination :page="page" :page-size="pageSize" :total="filtered.length" @update:page="page=$event" @update:page-size="pageSize=$event"/></section>
   <section class="cash-reconciliation"><p v-if="overview.gap!==null">已登记费用之外的资金差额：{{overview.gap}} USD（待核对）</p><span>当前资金核对 · 累计值</span><div><span>实际到账 <b>{{overview.netR??'—'}} R</b><small>{{overview.net??'—'}} USD</small></span><span>实际损耗{{overview.estimated?'（估算）':''}} <b>{{overview.lossR??'—'}} R</b><small>{{overview.loss??'—'}} USD</small></span></div><small>{{overview.lossReasons.join('；')||'仅用于核对资金，不再次扣入成本或净利润。'}}</small></section>
   <footer class="finance-footnote"><span>更新于 {{when(updated)}} · 每 {{refreshSeconds}} 秒更新</span><details><summary>折算口径与历史说明</summary><p>净利润＝消费收益 R − 开卡费 R − 充值手续费 R − 授权撤销费 R − 清算成本 R − 清算退款手续费 R。1 USD = 6.7 R；开卡费固定 0.50 USDT/张，按 1 USDT = 1 USD 记账，即 3.3500 R/张，包含已销卡。单卡结余扣本卡开卡费、撤销费和清算成本，充值手续费和未分摊的退款手续费统一在总账扣除。退款手续费按登记的发生时间分期，余额核对来源保留估算标记。</p><p>撤销费按当前配置比例估算，原币转 USD 使用各卡初始开卡结算比例；分项先汇总 USD 再折算 R，分期与单笔四舍五入可能有尾差。充值手续费按累计充值总账的 1% 计算，周期内总账下调可产生负数调整。缺失金额或折算依据时不显示完整净利润。</p><p>消费收益来自 Pro 账号的下游用户消耗。按北京时间从 Sub2 查询每日用户扣费，历史首次累计会自动补齐到实际消费日期；日、周、月使用同一组每日数据汇总。账号删除后保留已记录消耗和原下游标识。查询失败或历史缺失时保留原数据并标记待核对，不把未知金额记到今天。</p><p>实际损耗＝实际到账 − EJH 账户余额 − 正常及销卡中卡片余额折合 USD − 在途卡内付款折合 USD。资金余额使用最近查询值；该差额独立展示，不重复计入全部成本或利润。</p><p>本期快照内损耗变化：{{report.lossChange??'暂不可计算'}} USD<span v-if="report.firstAt">（{{when(report.firstAt)}} 至 {{when(report.lastAt)}}）</span>。仅有一期快照时无法计算变化。</p></details></footer>
  </template>
  <Teleport to="body"><div v-if="detail" class="modal-backdrop" @click.self="detail=null"><section class="finance-dialog" role="dialog" aria-modal="true" aria-label="收益与成本详情"><button class="icon-button" aria-label="关闭详情" @click="detail=null"><X :size="18"/></button><span class="eyebrow">{{labels[detail.kind]}}</span><h2>{{eventAmountR(detail)??'待核实'}} R</h2><p>原币 {{detail.kind==='consumption'?numR(detail.amount):numMoney(detail.amount)}} {{detail.currency}}<span v-if="detail.currency!=='USD'&&detail.usd!==null&&detail.usd!==undefined"> · {{numMoney(detail.usd)}} USD</span></p><dl><dt>时间</dt><dd>{{detail.day||(detail.month?(detail.month+'（日期未记录）'):when(detail.at))}}</dd><dt v-if="detail.card">卡片</dt><dd v-if="detail.card">{{detail.card}}</dd><dt v-if="detail.email">账号</dt><dd v-if="detail.email">{{detail.email}}</dd><dt>记录编号</dt><dd>{{detail.reference||detail.id}}</dd></dl><p>{{detail.note}}</p><p>{{detail.kind==='consumption'?'下游用户消费计为收益':'1 USD = 6.7 R'}}{{detail.kind==='opening'?' · USDT 按 1:1 USD 记账':''}}</p></section></div></Teleport>
 </div>
</template>
